function money(n){return new Intl.NumberFormat('en-ZM',{style:'currency',currency:'ZMW',maximumFractionDigits:2}).format(Number(n)||0)}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function toast(s){$('toast').textContent=s;$('toast').style.display='block';setTimeout(()=>$('toast').style.display='none',2500)}
function total(rows,type,area){return rows.filter(t=>(!type||t.type===type)&&(!area||t.area===area)).reduce((a,t)=>a+Number(t.amount||0),0)}
function tbl(rows,empty='No records yet.'){if(!rows.length)return `<div class="empty">${empty}</div>`;const headers=rows[0];return `<table><thead><tr>${headers.map(v=>`<th>${v}</th>`).join('')}</tr></thead><tbody>${rows.slice(1).map(r=>`<tr>${r.map((v,i)=>`<td data-label="${esc(String(headers[i]??'Details').replace(/<[^>]*>/g,''))}">${v}</td>`).join('')}</tr>`).join('')}</tbody></table>`}
function txTable(rows,actions=true){return [['Date','Area','Description','Type','Amount','Method',...(actions?['Action']:[])],...rows.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(t=>[esc(t.date),`<span class="pill">${esc(t.area)}</span>`,esc(t.description)+(t.notes?`<div class="small muted">${esc(t.notes)}</div>`:''),esc(t.type),`<span class="${t.type==='Income'?'in':'out'}">${t.type==='Income'?'+':'−'}${money(t.amount)}</span>`,esc(t.method||''),...(actions?[`<button class="danger small" onclick="delTx('${t.id}')">Delete</button>`]:[])])]}
