function leave(){closeMobileMenu();$('app').style.display='none';$('auth').style.display='grid';user=null;userRole=null;transactions=[];tenants=[];rentPayments=[];suppliers=[];payables=[];payablePayments=[];workers=[];payrollRecords=[];pupils=[];lunchPayments=[];schoolTests=[];testPayments=[];gradeFees=[];document.querySelectorAll('[data-page]').forEach(b=>b.classList.remove('hidden'));$('userAdminNav').classList.add('hidden');const transferForm=$('transferForm');if(transferForm){const panel=transferForm.closest('.panel');if(panel)panel.classList.remove('hidden');}}
