function renderPupils(){if(!$('pupilRows'))return;const q=($('pupilSearch').value||'').toLowerCase();$('pupilCount').textContent=pupils.length;const classNames=['Baby','Middle','Reception','Grade 1','Grade 2','Grade 3','Grade 4','Grade 5','Grade 6','Grade 7'];$('pupilClassCount').textContent=classNames.filter(c=>pupils.some(p=>String(p.class_name||'').trim().toLowerCase()===c.toLowerCase())).length;document.querySelectorAll('[data-class-count]').forEach(el=>{const cls=el.getAttribute('data-class-count');el.textContent=pupils.filter(p=>String(p.class_name||'').trim().toLowerCase()===cls.toLowerCase()).length});const gradeSel=$('classListGrade');if(gradeSel){const old=gradeSel.value;gradeSel.innerHTML='<option value="">Choose grade for class list</option>'+classNames.map(g=>`<option value="${g}">${g}</option>`).join('');gradeSel.value=classNames.includes(old)?old:'';}renderTransfers();renderGradeFees();const rows=[['Pupil name','Class / grade','Amount paid','Fees due','Requirements status','Pupil type','Balance','Phone','DATE / TERM / YEAR','Action']];pupils.filter(p=>!transactions.some(t=>String(t.category||'').toLowerCase()==='transfer'&&String(t.description||'').trim().toLowerCase()===String(p.full_name||'').trim().toLowerCase()&&String(t.notes||'').trim().toLowerCase()===String(p.class_name||'').trim().toLowerCase())).filter(p=>!q||`${p.full_name||''} ${p.class_name||''} ${p.guardian_phone||''} ${p.admission_number||''} ${p.guardian_name||''}`.toLowerCase().includes(q)).forEach(p=>{const lunch=lunchPayments.filter(r=>String(r.pupil_id)===String(p.id)&&String(r.payment_status||'Paid').toLowerCase()==='paid').reduce((sum,r)=>sum+Number(r.amount||0),0);const tests=testPayments.filter(r=>String(r.pupil_id)===String(p.id)&&String(r.payment_status||'Paid').toLowerCase()==='paid').reduce((sum,r)=>sum+Number(r.amount||0),0);const checks=Array.isArray(p.requirements_checklist)?p.requirements_checklist:[];const fee=Number(gradeFees.find(f=>String(f.grade_name||'').toLowerCase()===String(p.class_name||'').toLowerCase())?.fee_amount||0);const paid=Number(p.amount_paid||0);const balance=Math.max(0,fee-paid);const isNew=['NEW','NEWCOMER'].includes(String(p.pupil_type||'').toUpperCase());const complete=isNew&&newcomerRequirements.every(name=>checks.includes(name));const reqStatus=isNew?(complete?'<span style="color:#137b56;font-weight:900;font-size:18px" title="All requirements received">✓</span>':'<span style="color:#b93838;font-weight:900;font-size:18px" title="Requirements incomplete">✗</span>'):'—';rows.push([esc(p.full_name),esc(p.class_name||''),`<input data-pupil-paid="${p.id}" type="number" min="0" step="0.01" value="${paid}" style="width:100px">`,money(fee),money(balance),`<select data-pupil-type="${p.id}" style="min-width:110px"><option ${!['NEW','NEWCOMER'].includes(p.pupil_type)?'selected':''}>NOT NEW</option><option ${['NEW','NEWCOMER'].includes(p.pupil_type)?'selected':''}>NEW</option></select>`,reqStatus,esc(p.guardian_phone||''),esc(String(p.enrollment_date||p.created_at||'').slice(0,10)+' / '+(p.term||'')+' / '+(p.school_year||'')),`<button class="soft small" type="button" onclick="editPupil('${p.id}')">EDIT</button> <button class="pupil-delete-x" type="button" title="Delete pupil" aria-label="Delete pupil" onclick="deletePupil('${p.id}')">×</button>`])});$('pupilRows').innerHTML=tbl(rows,'No pupils match your search.');}
$('pupilRows').addEventListener('change',async e=>{const typeId=e.target.dataset.pupilType,reqId=e.target.dataset.pupilReq,paidId=e.target.dataset.pupilPaid;if(paidId){const amount=Number(e.target.value||0);if(amount<0){appAlert('Amount paid cannot be negative.');return}const {error}=await sb.from('pupils').update({amount_paid:amount}).eq('id',paidId).eq('user_id',user.id);if(error){appAlert('Payment amount could not be updated: '+error.message);return}await loadRecords();toast('Pupil payment updated')}else if(typeId){const {error}=await sb.from('pupils').update({pupil_type:e.target.value,requirements_checklist:[]}).eq('id',typeId).eq('user_id',user.id);if(error){appAlert('Pupil type could not be updated: '+error.message);return}await loadRecords();toast('Pupil type updated')}else if(reqId!==undefined){const pupil=pupils.find(p=>String(p.id)===String(reqId));if(!pupil)return;let checks=Array.isArray(pupil.requirements_checklist)?[...pupil.requirements_checklist]:[];const name=newcomerRequirements[Number(e.target.dataset.reqIndex)];checks=e.target.checked?[...new Set([...checks,name])]:checks.filter(x=>x!==name);const {error}=await sb.from('pupils').update({requirements_checklist:checks}).eq('id',reqId).eq('user_id',user.id);if(error){appAlert('Requirement could not be updated: '+error.message);return}pupil.requirements_checklist=checks;toast('Requirement updated')}});
window.editPupil=function(id){const p=pupils.find(x=>String(x.id)===String(id));if(!p)return;editingPupilId=p.id;const set=(id,v)=>{const el=$(id);if(el)el.value=v??''};set('pupilName',p.full_name);set('pupilClass',p.class_name);set('guardianPhone',p.guardian_phone);set('pupilAmountPaid',p.amount_paid??0);set('pupilPaymentStatus',p.payment_status||'Paid');set('pupilPaymentMethod',p.payment_method||'Cash');set('pupilEnrollmentDate',p.enrollment_date||'');set('pupilTerm',p.term||'');set('pupilYear',p.school_year||new Date().getFullYear());set('pupilType',p.pupil_type||'NOT NEW');set('pupilDob',p.date_of_birth);set('pupilGuardianName',p.guardian_name);set('pupilAddress',p.home_address);set('pupilEmergencyPhone',p.emergency_contact_phone);set('pupilWelfareNotes',p.welfare_notes);document.querySelectorAll('.new-pupil-requirement').forEach(c=>c.checked=(p.requirements_checklist||[]).includes(c.value));$('newPupilRequirementsWrap').hidden=p.pupil_type!=='NEW';$('pupilSaveBtn').textContent='UPDATE PUPIL';$('pupilForm').scrollIntoView({behavior:'smooth',block:'start'});};
$('pupilForm').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,button=$('pupilSaveBtn')||form.querySelector('button[type=submit],button:not([type])');if(button){button.disabled=true;button.dataset.originalText=button.textContent;button.textContent='SAVING…'}try{const row={user_id:user.id,full_name:$('pupilName').value.trim(),class_name:$('pupilClass').value.trim(),guardian_phone:$('guardianPhone').value.trim()||null,admission_number:$('pupilAdmissionNo')?.value.trim()||null,date_of_birth:$('pupilDob').value||null,guardian_name:$('pupilGuardianName').value.trim()||null,guardian_email:$('pupilGuardianEmail')?.value.trim()||null,home_address:$('pupilAddress').value.trim()||null,emergency_contact_name:$('pupilEmergencyName')?.value.trim()||null,emergency_contact_phone:$('pupilEmergencyPhone').value.trim()||null,welfare_notes:$('pupilWelfareNotes').value.trim()||null,amount_paid:Number($('pupilAmountPaid').value||0),payment_status:$('pupilPaymentStatus').value,payment_method:$('pupilPaymentMethod').value,enrollment_date:$('pupilEnrollmentDate').value,term:$('pupilTerm').value,school_year:Number($('pupilYear').value),pupil_type:$('pupilType').value,requirements_checklist:$('pupilType').value==='NEW'?Array.from(document.querySelectorAll('.new-pupil-requirement:checked')).map(el=>el.value):[]};const result=editingPupilId?await sb.from('pupils').update(row).eq('id',editingPupilId):await sb.from('pupils').insert(row);const error=result.error;if(error){appAlert('Pupil could not be saved. Your entries have been kept. '+error.message);return}toast(editingPupilId?'Pupil profile updated':'Pupil saved');editingPupilId=null;form.reset();document.querySelectorAll('.new-pupil-requirement').forEach(el=>el.checked=false);$('pupilEnrollmentDate').value=today;if($('pupilYear')&&!$('pupilYear').value)$('pupilYear').value=new Date().getFullYear();$('pupilYear').value=new Date().getFullYear();await loadRecords()}catch(err){appAlert('Pupil could not be saved. Your entries have been kept. '+(err?.message||String(err)))}finally{if(button){button.disabled=false;button.textContent=button.dataset.originalText||'Save pupil'}}});

