 $('workerRows').innerHTML=tbl([['Worker','Job title','Department','Employment','Frequency','Basic salary (ZMW)','Contact','Status','Added','Edit'],...workers.map(w=>[esc(w.full_name),esc(w.job_title||''),esc(w.department||'Administration'),esc(w.employment_type||'Permanent'),esc(w.pay_frequency||'Monthly'),money(w.basic_salary),esc(w.phone||''),w.is_active===false?'Inactive':'Active',esc(String(w.created_at||'').slice(0,10)),`<button type="button" class="worker-edit-icon" title="Edit worker" aria-label="Edit ${esc(w.full_name)}" onclick="editWorker('${w.id}')">✎</button>`])],'No workers added yet.');
