 const rows=[['Pay period','Worker','Gross pay','NAPSA','Advance','Other deductions','Net pay','Method','Status','Edit / payslip']];
 payrollRecords.filter(r=>{const w=workers.find(x=>String(x.id)===String(r.worker_id));return (!q||(`${w?.full_name||'Worker'} ${r.pay_period||''}`).toLowerCase().includes(q))&&(!status||r.payment_status===status)}).forEach(r=>{const w=workers.find(x=>String(x.id)===String(r.worker_id));rows.push([esc(r.pay_period||''),esc(w?.full_name||`Worker #${r.worker_id}`),money(r.gross_pay??(Number(r.basic_pay||0)+Number(r.allowances||0)+Number(r.overtime_pay||0)+Number(r.bonus_pay||0)+Number(r.commission_pay||0))),money(r.napsa_amount),money(r.advance_deduction),money(r.other_deductions),`<b>${money(r.net_pay)}</b>`,esc(r.payment_method||''),`<button class="${r.payment_status==='Paid'?'soft':'primary'} small" onclick="togglePayrollStatus('${r.id}')">${esc(r.payment_status||'Pending Review')}</button>`,`<button type="button" class="worker-edit-icon" title="Edit payroll record" aria-label="Edit payroll record" onclick="editPayrollRecord('${r.id}')">✎</button>`])});
