window.toggleWorkerActive=async id=>{const w=workers.find(x=>String(x.id)===String(id));if(!w)return;const active=w.is_active===false;if(!await themedConfirm(`${active?'Reactivate':'Mark'} ${w.full_name} ${active?'as active':'as inactive'}? Historical payroll records will be preserved.`))return;const {error}=await sb.from('workers').update({is_active:active}).eq('id',id);if(error){appAlert('Could not update worker status: '+error.message);return}await loadRecords();toast(active?'Worker reactivated':'Worker marked inactive')};
function calcNetPay(){const val=id=>Number($(id)?.value)||0;const gross=val('basicPay')+val('allowances')+val('overtimePay')+val('bonusPay')+val('commissionPay');const selected=workers.find(w=>String(w.id)===String($('payrollWorker')?.value));const autoNapsa=String(selected?.job_title||'').trim().toLowerCase().includes('teacher')?Math.round(val('basicPay')*0.05*100)/100:0; if($('napsaDeduction'))$('napsaDeduction').value=autoNapsa.toFixed(2); const deductions=autoNapsa+val('advanceDeduction')+val('otherDeductions');$('grossPay').value=gross.toFixed(2);$('netPay').value=Math.max(0,gross-deductions).toFixed(2)}
