['basicPay','allowances','overtimePay','bonusPay','commissionPay','advanceDeduction','otherDeductions'].forEach(id=>$(id).addEventListener('input',calcNetPay)); $('napsaDeduction').readOnly=true; $('napsaDeduction').previousElementSibling.textContent='Employee NAPSA (automatically 5%)';$('payPeriod').value=today;$('payrollPaymentDate').value=today;
