$('payrollForm').addEventListener('submit',async e=>{e.preventDefault();const workerId=$('payrollWorker').value;const selectedWorker=workers.find(w=>String(w.id)===workerId);if(!selectedWorker){appAlert('Please select a worker.');return}const period=$('payPeriod').value;const isTeacher=String(selectedWorker.job_title||'').toLowerCase().includes('teacher');if(isTeacher&&[4,8,12].includes(Number(String(period).slice(5,7)))){appAlert('Teachers are not paid in April, August, or December. Record the applicable term-end pay under March, July or November, with payment scheduled for May, September or January.');return}const val=id=>Number($(id).value)||0,basic=val('basicPay'),allow=val('allowances'),overtime=val('overtimePay'),bonus=val('bonusPay'),commission=val('commissionPay'),napsa=isTeacher?Math.round(basic*0.05*100)/100:0,advance=val('advanceDeduction'),other=val('otherDeductions'),gross=basic+allow+overtime+bonus+commission,net=gross-napsa-advance-other;if([basic,allow,overtime,bonus,commission,napsa,advance,other].some(n=>!Number.isFinite(n)||n<0)||net<0){appAlert('Check payroll amounts. Amounts cannot be negative and total deductions cannot exceed gross pay.');return}const paymentDate=$('payrollPaymentDate').value||null;const dueMonth=({3:5,7:9,11:1})[Number(period.slice(5,7))];if(isTeacher&&dueMonth&&paymentDate&&Number(paymentDate.slice(5,7))!==dueMonth){appAlert('Teacher contract: March pay is paid in May, July pay in September, and November pay in January.');return}const row={user_id:user.id,worker_id:Number(workerId),pay_period:period,basic_pay:basic,allowances:allow,overtime_pay:overtime,bonus_pay:bonus,commission_pay:commission,gross_pay:gross,paye_amount:0,napsa_rate:0,napsa_amount:napsa,nhima_amount:0,advance_deduction:advance,other_deductions:other,net_pay:net,payment_status:$('paymentStatus').value,payment_method:$('payrollMethod').value,payment_date:paymentDate,payment_reference:$('payrollReference').value.trim()||null,approved_at:$('paymentStatus').value==='Approved'||$('paymentStatus').value==='Paid'?new Date().toISOString():null};const {error}=await sb.from('payroll_records').insert(row);if(error){appAlert('Payroll record could not be saved: '+error.message);return}e.target.reset();$('payPeriod').value=today;$('payrollPaymentDate').value=today;['allowances','overtimePay','bonusPay','commissionPay','napsaDeduction','advanceDeduction','otherDeductions'].forEach(id=>$(id).value='0');calcNetPay();await loadRecords();toast('Payroll record saved')});
window.togglePayrollStatus=async id=>{const r=payrollRecords.find(x=>String(x.id)===String(id));if(!r)return;const current=String(r.payment_status||'Pending Review');const next=current==='Pending Review'?'Approved':current==='Approved'?'Paid':'Pending Review';const w=workers.find(x=>String(x.id)===String(r.worker_id));if(next==='Paid'&&String(w?.job_title||'').toLowerCase().includes('teacher')&&[4,8,12].includes(Number(String(r.pay_period||'').slice(5,7)))){appAlert('Teachers are not paid in April, August, or December.');return}const dueMonth=({3:5,7:9,11:1})[Number(String(r.pay_period||'').slice(5,7))];if(next==='Paid'&&String(w?.job_title||'').toLowerCase().includes('teacher')&&dueMonth&&Number(String(r.payment_date||today).slice(5,7))!==dueMonth){appAlert('Teacher contract: March pay is paid in May, July pay in September, and November pay in January. Update the payment date first.');return}if(!await themedConfirm(`Move this payroll record to ${next}?`))return;const {error}=await sb.from('payroll_records').update({payment_status:next,approved_at:next==='Approved'||next==='Paid'?new Date().toISOString():null,payment_date:next==='Paid'?(r.payment_date||today):r.payment_date}).eq('id',id);if(error){appAlert('Could not update payroll status: '+error.message);return}await loadRecords();toast(`Payroll marked ${next.toLowerCase()}`)};

window.printPayrollSlip=id=>{const r=payrollRecords.find(x=>String(x.id)===String(id));if(!r)return;const w=workers.find(x=>String(x.id)===String(r.worker_id))||{};const lines=[['Basic pay',r.basic_pay],['Allowances',r.allowances],['Overtime',r.overtime_pay],['Bonus',r.bonus_pay],['Commission',r.commission_pay],['Gross pay',r.gross_pay],['Employee NAPSA',-Number(r.napsa_amount||0)],['Advance / loan deduction',-Number(r.advance_deduction||0)],['Other deductions',-Number(r.other_deductions||0)],['NET PAY',r.net_pay]];const win=window.open('','_blank','width=720,height=850');if(!win){appAlert('Allow pop-ups to print the payslip.');return}win.document.write(`<html><head><title>Payslip</title><style>body{font:14px Arial;color:#17324d;padding:28px}h1{color:#064b87}table{width:100%;border-collapse:collapse;margin-top:20px}td,th{padding:10px;border-bottom:1px solid #d6e1ec;text-align:left}td:last-child{text-align:right}.net{font-weight:bold;background:#edf5ff}@media print{button{display:none}}</style></head><body><h1>THE GRATEFUL COLLECTIVE</h1><h2>Employee Payslip</h2><p><b>Employee:</b> ${esc(w.full_name||'Worker')} &nbsp; <b>Job title:</b> ${esc(w.job_title||'')}</p><p><b>Department:</b> ${esc(w.department||'')} &nbsp; <b>Period:</b> ${esc(r.pay_period||'')}</p><p><b>Status:</b> ${esc(r.payment_status||'Pending Review')} &nbsp; <b>Payment reference:</b> ${esc(r.payment_reference||'—')}</p><table><thead><tr><th>Pay item</th><th>Amount (ZMW)</th></tr></thead><tbody>${lines.map(([label,amount])=>`<tr class="${label==='NET PAY'?'net':''}"><td>${esc(label)}</td><td>${money(Math.abs(Number(amount||0)))}</td></tr>`).join('')}</tbody></table><p>Statutory amounts must be checked against current requirements. Keep this document confidential.</p><button onclick="window.print()">Print / Save as PDF</button>

<\/body></html>`);win.document.close()};
$('exportPayroll').onclick=()=>{const rows=[['Pay period','Worker','Job title','Department','Basic pay ZMW','Allowances ZMW','Overtime ZMW','Bonus ZMW','Commission ZMW','Gross pay ZMW','PAYE ZMW','Employee NAPSA ZMW','NHIMA ZMW','Advance deduction ZMW','Other deductions ZMW','Net pay ZMW','Payment method','Payment date','Payment reference','Payment status'],...payrollRecords.map(r=>{const w=workers.find(x=>String(x.id)===String(r.worker_id));return [r.pay_period,w?.full_name||`Worker #${r.worker_id}`,w?.job_title||'',w?.department||'',r.basic_pay,r.allowances,r.overtime_pay,r.bonus_pay,r.commission_pay,r.gross_pay,r.paye_amount,r.napsa_amount,r.nhima_amount,r.advance_deduction,r.other_deductions,r.net_pay,r.payment_method,r.payment_date,r.payment_reference,r.payment_status]})];const data=rows.map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');const blob=new Blob(['\ufeff'+data],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='grateful-collective-payroll.csv';a.click();URL.revokeObjectURL(url)};

