 const stockQ=($('gcStockSearch')?.value||'').toLowerCase().trim(),stockShop=$('gcStockShopFilter')?.value||'',stockStatus=$('gcStockStatusFilter')?.value||'';const filteredProducts=gcProducts.filter(p=>(!stockShop||p.shop===stockShop)&&(!stockStatus||(stockStatus==='out'?Number(p.quantity)<=0:Number(p.quantity)>0&&Number(p.quantity)<=Number(p.reorder_level||0)))&&(!stockQ||[p.product_name,p.product_code,p.barcode,p.category,p.supplier_name,p.shop].some(v=>String(v||'').toLowerCase().includes(stockQ))));$('gcStockRows').innerHTML=tbl([['Shop','Product / code','Category / supplier','Quantity','Alert at','Unit cost','Selling price','Stock value','Actions'],...filteredProducts.map(p=>[esc(p.shop),esc(p.product_name)+(p.product_code?`<div class="small muted">${esc(p.product_code)} ${p.barcode?'· '+esc(p.barcode):''}</div>`:''),esc(p.category||'—')+'<div class="small muted">'+esc(p.supplier_name||'')+'</div>',Number(p.quantity),Number(p.reorder_level||0),money(p.unit_cost),money(p.selling_price),money(Number(p.quantity)*Number(p.unit_cost)),`<button class="soft small" onclick="gcEditProduct(${p.id})">Edit</button> <button class="danger small" onclick="gcDeleteProduct(${p.id})">Delete</button> <button class="soft small" onclick="gcAdjustStock(${p.id},'DAMAGE')">Damage</button> <button class="soft small" onclick="gcAdjustStock(${p.id},'EXPIRED')">Expired</button>`])],'No stock items match this filter.');const low=gcProducts.filter(p=>Number(p.quantity)<=Number(p.reorder_level||0));$('gcLowStockRows').innerHTML=tbl([['Shop','Product','In stock','Alert at','Status'],...low.map(p=>[esc(p.shop),esc(p.product_name),Number(p.quantity),Number(p.reorder_level||0),Number(p.quantity)<=0?'OUT OF STOCK':'LOW STOCK'])],'All products are above their low-stock threshold.');
