async function gcLoadShopAdvanced(){
 if(!sb||!user||!['administrator','shop_manager'].includes(userRole))return;
 const specs=[['gc_shop_sales','sale_date'],['gc_shop_sale_items','id'],['gc_shop_customers','customer_name'],['gc_shop_customer_payments','payment_date']];
 const rs=await Promise.all(specs.map(([t,o])=>sb.from(t).select('*').order(o,{ascending:false}).limit(1500)));
 const names=['gcShopSales','gcShopSaleItems','gcShopCustomers','gcShopCustomerPayments'];
 rs.forEach((r,i)=>{if(!r.error)window[names[i]]=r.data||[];else window[names[i]]=[]});
 gcShopSales=window.gcShopSales||[];gcShopSaleItems=window.gcShopSaleItems||[];gcShopCustomers=window.gcShopCustomers||[];gcShopCustomerPayments=window.gcShopCustomerPayments||[];
}
function gcShopReceipt(s){const item=gcShopSaleItems.find(i=>String(i.sale_id)===String(s.id)),p=gcProducts.find(x=>String(x.id)===String(item?.product_id));return `<div style="font-family:monospace;max-width:420px;margin:auto;padding:16px;background:white;color:#111"><h2 style="text-align:center">THE GRATEFUL COLLECTIVE</h2><h3 style="text-align:center">${esc(s.shop)} RECEIPT</h3><p>Receipt: ${esc(s.receipt_number||s.id)}<br>Date: ${esc(s.sale_date)}<br>Customer: ${esc(s.customer_name||'Walk-in customer')}</p><hr><p>${esc(p?.product_name||item?.product_name||'Product')} × ${Number(item?.quantity||0)} @ ${money(item?.unit_price)}<br>Subtotal: ${money(s.subtotal)}<br>Discount: ${money(s.discount)}<br><b>Total: ${money(s.total)}</b><br>Paid: ${money(s.amount_paid)}<br>Balance: ${money(Math.max(0,Number(s.total||0)-Number(s.amount_paid||0)))}</p><p>Payment: ${esc(s.payment_method||'')}</p><p style="text-align:center">Thank you!</p></div>`}
function gcRenderShopAdvanced(){
 if(!$('gcSalesRows'))return;
 const q=($('gcSalesSearch')?.value||'').toLowerCase().trim(),shop=$('gcSalesShopFilter')?.value||'';
 const sales=gcShopSales.filter(s=>(!shop||s.shop===shop)&&(!q||[s.receipt_number,s.shop,s.customer_name,s.customer_phone,s.sale_date,s.payment_method,s.status].some(v=>String(v||'').toLowerCase().includes(q))));
 $('gcSalesRows').innerHTML=tbl([['Date','Receipt','Shop','Customer','Total','Paid','Balance','Method','Status','Actions'],...sales.slice(0,200).map(s=>[esc(s.sale_date),esc(s.receipt_number||s.id),esc(s.shop),esc(s.customer_name||'Walk-in'),money(s.total),money(s.amount_paid),money(Math.max(0,Number(s.total||0)-Number(s.amount_paid||0))),esc(s.payment_method||''),esc(s.status||'COMPLETED'),`<button class="soft small" onclick="gcPrintReceipt(${s.id})">Receipt</button> ${s.status==='COMPLETED'?`<button class="soft small" onclick="gcCancelSale(${s.id})">Cancel</button>`:''}`])],'No sales recorded yet.');
 $('gcCustomerRows').innerHTML=tbl([['Customer','Phone','Credit outstanding','Notes'],...gcShopCustomers.map(c=>{const due=gcShopSales.filter(s=>String(s.customer_id)===String(c.id)&&s.status==='COMPLETED').reduce((a,s)=>a+Math.max(0,Number(s.total||0)-Number(s.amount_paid||0)),0);return [esc(c.customer_name),esc(c.phone||''),money(due),esc(c.notes||'')]})],'No customers recorded.');
 const open=gcShopSales.filter(s=>s.status==='COMPLETED'&&Number(s.total||0)>Number(s.amount_paid||0));$('gcCreditSale').innerHTML='<option value="">Choose credit sale</option>'+open.map(s=>`<option value="${s.id}">${esc(s.receipt_number||s.id)} — ${esc(s.customer_name||'Customer')} — balance ${money(Number(s.total)-Number(s.amount_paid))}</option>`).join('');
 $('gcCreditRows').innerHTML=tbl([['Date','Customer','Receipt','Amount','Method','Notes'],...gcShopCustomerPayments.map(p=>{const s=gcShopSales.find(x=>String(x.id)===String(p.sale_id));return [esc(p.payment_date),esc(s?.customer_name||'Customer'),esc(s?.receipt_number||p.sale_id),money(p.amount),esc(p.payment_method||''),esc(p.notes||'')]})],'No credit payments recorded.');
 const loss=gcMovements.filter(m=>['DAMAGE','EXPIRED','ADJUSTMENT'].includes(m.movement_type));$('gcLossRows').innerHTML=tbl([['Date','Shop','Product','Type','Quantity','Notes'],...loss.map(m=>[esc(m.movement_date),esc(m.shop),esc(gcProducts.find(p=>String(p.id)===String(m.product_id))?.product_name||''),esc(m.movement_type),Number(m.quantity||0),esc(m.description||'')])],'No damage/expiry adjustments recorded.');
 const saleProduct=$('gcSaleProduct'),old=saleProduct.value;saleProduct.innerHTML='<option value="">Choose product</option>'+gcProducts.filter(p=>p.shop===$('gcSaleShop').value&&Number(p.quantity)>0).map(p=>`<option value="${p.id}">${esc(p.product_name)} (stock ${p.quantity})</option>`).join('');if(gcProducts.some(p=>String(p.id)===old&&p.shop===$('gcSaleShop').value))saleProduct.value=old;gcSalePriceUpdate();
}
function gcSalePriceUpdate(){const p=gcProducts.find(x=>String(x.id)===$('gcSaleProduct')?.value);if(!p){if($('gcSalePreview'))$('gcSalePreview').textContent='Select a product to calculate the receipt total.';return}if(!$('gcSalePrice').dataset.manual)$('gcSalePrice').value=Number(p.selling_price).toFixed(2);const subtotal=Number($('gcSaleQty').value||0)*Number($('gcSalePrice').value||0),discount=Number($('gcSaleDiscount').value||0);$('gcSalePreview').textContent=`Available stock: ${p.quantity} · Subtotal: ${money(subtotal)} · Discount: ${money(discount)} · Total due: ${money(Math.max(0,subtotal-discount))}`;if(!$('gcSalePaid').dataset.manual)$('gcSalePaid').value=$('gcSaleMethod').value==='Credit'?'0':Math.max(0,subtotal-discount).toFixed(2)}
window.gcPrintReceipt=id=>{const s=gcShopSales.find(x=>String(x.id)===String(id));if(!s)return;const w=window.open('','_blank','width=500,height=700');if(!w){appAlert('Allow pop-ups to print the receipt.');return}w.document.write('<html><head><title>Receipt</title><style>body{font:14px Arial;padding:12px}@media print{button{display:none}}</style></head><body>'+gcShopReceipt(s)+'<button onclick="window.print()">Print receipt</button>\\n<\/body></html>');w.document.close()};
window.gcCancelSale=async id=>{const s=gcShopSales.find(x=>String(x.id)===String(id));if(!s||s.status!=='COMPLETED')return;if(!await themedConfirm('Cancel this sale and restore its item to stock? A refund expense will be recorded for the amount paid; verify the actual refund channel.'))return;const item=gcShopSaleItems.find(i=>String(i.sale_id)===String(id));const {error}=await sb.from('gc_shop_sales').update({status:'CANCELLED'}).eq('id',id);if(error){appAlert(error.message);return}if(item){const p=gcProducts.find(x=>String(x.id)===String(item.product_id));if(p)await sb.from('gc_shop_products').update({quantity:Number(p.quantity)+Number(item.quantity),updated_at:new Date().toISOString()}).eq('id',p.id)}await sb.from('gc_shop_movements').update({movement_type:'CANCELLED',description:`Cancelled receipt ${s.receipt_number}`}).eq('user_id',user.id).ilike('description',`%${s.receipt_number}%`);if(Number(s.amount_paid)>0){const refund=await sb.from('transactions').insert({user_id:user.id,date:today,type:'Expense',area:'Shop',category:s.shop+' | Refund',description:`Refund for cancelled receipt ${s.receipt_number}`,amount:Number(s.amount_paid),method:s.payment_method==='Part-paid / credit'?'Cash':s.payment_method,notes:'Refund entered when cancelling a sale; verify actual payment channel.'});if(refund.error)appAlert('Sale cancelled, but the refund expense could not be posted. Record it manually: '+refund.error.message)}await gcLoadExtra();gcRenderExtra();toast('Sale cancelled; verify any cash refund separately')};
