['gcSaleProduct','gcSaleShop','gcSaleQty','gcSaleDiscount','gcSaleMethod'].forEach(id=>$(id).addEventListener(id==='gcSaleShop'||id==='gcSaleProduct'?'change':'input',()=>{if(id==='gcSaleShop'){ $('gcSaleProduct').value='';$('gcSalePrice').dataset.manual='';gcRenderShopAdvanced()}if(id==='gcSaleProduct')$('gcSalePrice').dataset.manual='';if(id==='gcSaleMethod')$('gcSalePaid').dataset.manual='';gcSalePriceUpdate()}));$('gcSalePrice').addEventListener('input',()=>{$('gcSalePrice').dataset.manual='1';gcSalePriceUpdate()});$('gcSalePaid').addEventListener('input',()=>$('gcSalePaid').dataset.manual='1');$('gcSalesSearch').addEventListener('input',gcRenderShopAdvanced);$('gcSalesShopFilter').addEventListener('change',gcRenderShopAdvanced);
$('gcSaleForm').addEventListener('submit',async e=>{e.preventDefault();const p=gcProducts.find(x=>String(x.id)===$('gcSaleProduct').value),qty=Number($('gcSaleQty').value),price=Number($('gcSalePrice').value),discount=Number($('gcSaleDiscount').value||0),subtotal=qty*price,total=Math.max(0,subtotal-discount),paid=Number($('gcSalePaid').value||0),method=$('gcSaleMethod').value;if(!p||p.shop!==$('gcSaleShop').value||qty<=0||qty>Number(p.quantity)||price<0||discount<0||discount>subtotal||paid<0||paid>total){appAlert('Check product, stock quantity, price, discount and amount received.');return}if(method==='Credit'&&(!$('gcSaleCustomer').value.trim()||!$('gcSalePhone').value.trim())){appAlert('For a credit sale, enter the customer name and phone so the balance can be followed up.');return}let customer=null;const cname=$('gcSaleCustomer').value.trim(),phone=$('gcSalePhone').value.trim();if(cname){customer=gcShopCustomers.find(c=>c.customer_name.toLowerCase()===cname.toLowerCase()&&String(c.phone||'')===phone);if(!customer){const cr=await sb.from('gc_shop_customers').insert({user_id:user.id,customer_name:cname,phone:phone||null,notes:null}).select().single();if(cr.error){appAlert('Could not save customer: '+cr.error.message);return}customer=cr.data;gcShopCustomers.push(customer)}}const receipt='GC-'+$('gcSaleShop').value.replace(/[^A-Z]/g,'').slice(0,3)+'-'+Date.now().toString().slice(-8);const sr=await sb.from('gc_shop_sales').insert({user_id:user.id,receipt_number:receipt,shop:p.shop,customer_id:customer?.id||null,customer_name:cname||'Walk-in customer',customer_phone:phone||null,sale_date:$('gcSaleDate').value,subtotal,discount,total,amount_paid:paid,payment_method:method,status:'COMPLETED',notes:$('gcSaleNotes').value.trim()||null}).select().single();if(sr.error){appAlert('Sale could not be saved: '+sr.error.message);return}const ir=await sb.from('gc_shop_sale_items').insert({user_id:user.id,sale_id:sr.data.id,product_id:p.id,product_name:p.product_name,quantity:qty,unit_price:price,unit_cost:Number(p.unit_cost||0),line_total:total});if(ir.error){await sb.from('gc_shop_sales').update({status:'CANCELLED'}).eq('id',sr.data.id);appAlert('Receipt header saved but item failed; sale was marked cancelled. '+ir.error.message);return}const upd=await sb.from('gc_shop_products').update({quantity:Number(p.quantity)-qty,updated_at:new Date().toISOString()}).eq('id',p.id);if(upd.error){appAlert('Sale was saved but stock update failed; reconcile this sale before continuing: '+upd.error.message);return}await sb.from('gc_shop_movements').insert({user_id:user.id,product_id:p.id,shop:p.shop,movement_date:$('gcSaleDate').value,movement_type:'SALE',quantity:qty,unit_price:price,amount:total,description:`Receipt ${receipt}; ${method}; discount ${discount}`});if(paid>0){const tx=await sb.from('transactions').insert({user_id:user.id,date:$('gcSaleDate').value,type:'Income',area:'Shop',category:p.shop+' | Sales',description:`Shop sale ${receipt} — ${p.product_name}`,amount:paid,method:method==='Credit'?'Other':method,notes:`Receipt ${receipt}; total ${total}; discount ${discount}; amount received ${paid}`});if(tx.error)appAlert('Sale and stock were saved, but accounting income could not be posted. Add an Income transaction for '+money(paid)+' manually. '+tx.error.message)}await gcLoadExtra();gcRenderExtra();gcRenderShopAdvanced();$('gcReceiptPreview').innerHTML=gcShopReceipt(sr.data)+'<div class="actions"><button type="button" class="primary" onclick="gcPrintReceipt('+sr.data.id+')">Print receipt</button></div>';$('gcReceiptPreview').classList.remove('hidden');e.target.reset();$('gcSaleDate').value=today;$('gcSaleQty').value='1';$('gcSaleDiscount').value='0';$('gcSalePaid').value='0';$('gcSalePrice').dataset.manual='';$('gcSalePaid').dataset.manual='';gcSalePriceUpdate();toast('Sale recorded and stock reduced')});
