$('gcBackup').onclick=async()=>{if(!sb||!user)return;const names=['transactions','rental_units','rental_payments','suppliers','trade_payables','trade_payable_payments','workers','payroll_records','pupils','lunch_payments','school_tests','test_payments','school_grade_fees','gc_transfers','gc_reconciliation','gc_shop_products','gc_shop_movements','gc_shop_customers','gc_shop_sales','gc_shop_sale_items','gc_shop_customer_payments','gc_audit_log','gc_expense_management','gc_expense_recurring','gc_petty_cash','gc_expense_budgets'];const out={app:'THE GRATEFUL COLLECTIVE',format_version:1,exported_at:new Date().toISOString(),user_id:user.id,tables:{}};for(const name of names){const {data,error}=await sb.from(name).select('*');if(error){appAlert(`Backup stopped at ${name}: ${error.message}. Confirm migration/table permissions; no partial file was downloaded.`);return}out.tables[name]=data||[]}const blob=new Blob([JSON.stringify(out,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='grateful-collective-backup-'+today+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Backup exported')};
