$('gcRestoreButton').onclick=()=>{if(!confirm('Restore will upsert records from the selected backup and may overwrite matching record IDs. Export a fresh backup first. Continue?'))return;$('gcRestoreFile').click()};
$('gcRestoreFile').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{const backup=JSON.parse(await file.text());if(backup.app!=='THE GRATEFUL COLLECTIVE'||!backup.tables||backup.user_id!==user.id){appAlert('This is not a valid backup for the signed-in account.');return}const order=['school_grade_fees','suppliers','workers','pupils','rental_units','school_tests','transactions','rental_payments','lunch_payments','test_payments','payroll_records','trade_payables','trade_payable_payments','gc_shop_products','gc_shop_movements','gc_shop_customers','gc_shop_sales','gc_shop_sale_items','gc_shop_customer_payments','gc_transfers','gc_reconciliation'];for(const table of order){const rows=backup.tables[table];if(!Array.isArray(rows)||!rows.length)continue;const safe=rows.filter(r=>r.user_id===user.id);if(safe.length!==rows.length)throw new Error(`Backup contains records not owned by the signed-in account in ${table}.`);const {error}=await sb.from(table).upsert(safe,{onConflict:'id'});if(error)throw new Error(`${table}: ${error.message}`)}await loadRecords();appAlert('Restore finished. Verify the dashboard, pupils, rentals, payables and stock before continuing. Audit history itself is intentionally not replayed as new events.');}catch(err){appAlert('Restore stopped: '+err.message+' Some earlier tables may already have been restored. Export a backup and inspect the records before retrying.')}finally{e.target.value=''}});

