/* Accessibility polish: announce the current section and label dynamically rendered tables. */
(function gcUsabilityPolish(){
 const side=document.getElementById('side');
 const isMobile=()=>window.matchMedia('(max-width:650px)').matches;
 const markCurrent=()=>{
  const active=document.querySelector('.page:not(.hidden)');const id=active?.id?.replace(/^page-/,'');
  document.querySelectorAll('[data-page]').forEach(b=>{if(b.dataset.page===id)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});
  document.querySelectorAll('[data-quick-page]').forEach(b=>{const q=b.dataset.quickPage;const current=(q==='home'&&id==='dashboard')||(q==='records'&&id===(userRole==='school_staff'?'pupils':userRole==='shop_manager'?'shops':'transactions'));if(current)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});
 };
 const labelTables=()=>document.querySelectorAll('.tablewrap table').forEach(table=>{
  const headers=[...table.querySelectorAll('thead th')].map(th=>th.textContent.trim());
  table.querySelectorAll('tbody tr').forEach(row=>[...row.cells].forEach((cell,i)=>{if(!cell.hasAttribute('data-label')&&headers[i])cell.setAttribute('data-label',headers[i])}));
  if(!table.hasAttribute('aria-label')){const h=table.closest('.panel')?.querySelector('h3')?.textContent?.trim();if(h)table.setAttribute('aria-label',h)}
 });
 const sideToggle=document.getElementById('sideToggle');if(sideToggle){sideToggle.setAttribute('aria-controls','side');sideToggle.setAttribute('aria-label','Toggle navigation');}
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&side?.classList.contains('open')){closeMobileMenu();sideToggle?.focus({preventScroll:true})}});
 document.querySelectorAll('#side [data-page]').forEach(b=>b.addEventListener('click',()=>{if(isMobile())closeMobileMenu()}));
 const originalPage=window.page;if(typeof originalPage==='function'&&!originalPage.__gcUsabilityWrapped){const wrapped=async function(...args){const result=await originalPage.apply(this,args);markCurrent();return result};wrapped.__gcUsabilityWrapped=true;window.page=wrapped}
 labelTables();markCurrent();const observer=new MutationObserver(()=>{labelTables();markCurrent()});observer.observe(document.getElementById('app')||document.body,{childList:true,subtree:true,attributes:true,attributeFilter:['class']});
 window.addEventListener('resize',()=>{if(!isMobile()&&side?.classList.contains('open'))closeMobileMenu()},{passive:true});
})();


