 function render(){if(!$('gcReportDetailRows'))return;const rows=rowsFor();const inc=rows.filter(t=>String(t.type).toLowerCase()==='income').reduce((a,t)=>a+Number(t.amount||0),0),out=rows.filter(t=>String(t.type).toLowerCase()==='expense').reduce((a,t)=>a+Number(t.amount||0),0);$('gcReportDetailCount').textContent=rows.length;$('gcReportDetailIncome').textContent=money(inc);$('gcReportDetailExpenses').textContent=money(out);$('gcReportDetailNet').textContent=money(inc-out);$('gcReportDetailRows').innerHTML=typeof tbl==='function'?tbl([['Date','Area','Category','Description','Type','Amount','Method'],...rows.slice().sort((a,b)=>String(b.date).localeCompare(String(a.date))).map(t=>[escv(t.date),escv(t.area),escv(t.category||''),escv(t.description||''),escv(t.type),money(t.amount),escv(t.method||'')])],'No transactions match these filters.'):'';
 const categories={};rows.filter(t=>String(t.type).toLowerCase()==='expense').forEach(t=>{const k=t.category||t.area||'Uncategorised';categories[k]=(categories[k]||0)+Number(t.amount||0)});const catRows=Object.entries(categories).sort((a,b)=>b[1]-a[1]);$('gcReportCategoryRows').innerHTML=typeof tbl==='function'?tbl([['Expense category','Total'],...catRows.map(([k,v])=>[escv(k),money(v)])],'No expenses in this period.'):'';
 }
 function mount(){const page=$('page-reports');if(!page||$('gcReportTools'))return;const panel=document.createElement('section');panel.className='gc-report-tools';panel.id='gcReportTools';panel.innerHTML=`<h3>Company transaction analysis</h3><p class="hint">Filter company transactions, inspect category totals and export the underlying records. Totals below cover the filtered transaction list; receipts stored in separate rental, lunch, test or payroll records remain in their dedicated report summaries.</p><div class="gc-report-filters"><div><label for="gcReportSearch">Search records</label><input id="gcReportSearch" placeholder="Description, category, reference…"></div><div><label for="gcReportArea">Business area</label><select id="gcReportArea"><option value="">All areas</option><option>School</option><option>Shop</option><option>Rentals</option><option>Company</option></select></div><div><label for="gcReportType">Transaction type</label><select id="gcReportType"><option value="">Income and expenses</option><option value="Income">Income</option><option value="Expense">Expense</option></select></div><div><label>Matching records</label><div class="statvalue" id="gcReportDetailCount">0</div></div></div><div class="cards" style="margin-top:12px"><div class="card"><div class="statlabel">FILTERED INCOME</div><div class="statvalue" id="gcReportDetailIncome">K0.00</div></div><div class="card"><div class="statlabel">FILTERED EXPENSES</div><div class="statvalue" id="gcReportDetailExpenses">K0.00</div></div><div class="card"><div class="statlabel">FILTERED NET</div><div class="statvalue" id="gcReportDetailNet">K0.00</div></div></div><div class="gc-report-actions"><button type="button" class="primary" id="gcReportExport">Export filtered CSV</button><button type="button" class="soft" id="gcReportPrint">Print reports</button><button type="button" class="soft" id="gcReportReset">Clear filters</button></div><div class="gc-report-breakdown"><div class="panel"><h3>Expense category breakdown</h3><div class="tablewrap" id="gcReportCategoryRows"></div></div><div class="panel"><h3>Filtered transaction details</h3><div class="tablewrap" id="gcReportDetailRows"></div></div></div>`;
 const anchor=page.querySelector('#reportRows')?.closest('.panel');if(anchor)anchor.insertAdjacentElement('afterend',panel);else page.appendChild(panel);
 ['gcReportSearch','gcReportArea','gcReportType','from','to'].forEach(id=>$(id)?.addEventListener(id==='gcReportSearch'?'input':'change',render));$('gcReportExport').onclick=()=>{const rows=rowsFor();download('grateful-collective-filtered-transactions.csv',[['Date','Area','Category','Description','Type','Amount','Method','Notes'],...rows.map(t=>[t.date,t.area,t.category,t.description,t.type,t.amount,t.method,t.notes])])};$('gcReportPrint').onclick=()=>window.print();$('gcReportReset').onclick=()=>{['gcReportSearch','gcReportArea','gcReportType'].forEach(id=>$(id).value='');render()};render();}
 const oldPage=window.page;if(typeof oldPage==='function'&&!oldPage.__gcReportEnh){const wrapped=async function(...args){const r=await oldPage.apply(this,args);if(args[0]==='reports'){mount();render()}return r};wrapped.__gcReportEnh=true;window.page=wrapped;}
 document.addEventListener('input',e=>{if(e.target?.id==='gcReportSearch')render()});document.addEventListener('change',e=>{if(['gcReportArea','gcReportType','from','to'].includes(e.target?.id))render()});
